36: // Recorrer el menú para verificar si la URL y los parámetros existen
37: function checkUrlExists(menuItems: any, targetUrl: string, params: any) {
38:   return menuItems.some((item: any) => {
39:     // Verificar la URL y los parámetros
40:     if (item.Url === targetUrl && checkParams(item.Params, params)) {
41:       return true;
42:     }
43:     if (item.Opciones && item.Opciones.length > 0) {
44:       return checkUrlExists(item.Opciones, targetUrl, params);
45:     }
46:     return false;
47:   });
48: }
49: 
50: // Verificar los parámetros de la ruta
51: function checkParams(expectedParams: any, actualParams: any): boolean {
52:   if (!expectedParams) {
53:     return true;
54:   }
55:   for (let key in expectedParams) {
56:     if (expectedParams[key] !== actualParams[key]) {
57:       return false;
58:     }
59:   }
60:   return true;
61: }

